public class AuthClient {
    private static final Duration DEFAULT_TIMEOUT = Duration.ofSeconds(30);
    private static final String TIMEOUT_ENV_VAR = "AUTH_TIMEOUT_SECONDS";

    private final HttpClient http = HttpClient.newHttpClient();
    private final Duration timeout;

    public AuthClient() {
        this(timeoutFromEnv());
    }

    public AuthClient(Duration timeout) {
        this.timeout = timeout;
    }

    private static Duration timeoutFromEnv() {
        String value = System.getenv(TIMEOUT_ENV_VAR);
        if (value == null || value.isBlank()) {
            return DEFAULT_TIMEOUT;
        }
        try {
            return Duration.ofSeconds(Long.parseLong(value.trim()));
        } catch (NumberFormatException e) {
            return DEFAULT_TIMEOUT;
        }
    }

    public String refreshToken(URI authServer, String refreshToken) throws Exception {
        HttpRequest request = HttpRequest.newBuilder(authServer.resolve("/oauth/token"))
                .timeout(timeout)
                .POST(HttpRequest.BodyPublishers.ofString("grant_type=refresh_token&refresh_token=" + refreshToken))
                .build();
        return http.send(request, HttpResponse.BodyHandlers.ofString()).body();
    }
}

