package demo;

import java.lang.reflect.Field;
import java.net.URI;
import java.net.http.HttpRequest;
import java.time.Duration;

public class TestMain {
    public static void main(String[] args) throws Exception {
        // Default (30s) case
        AuthClient defaultClient = new AuthClient();
        Duration defaultTimeout = getTimeout(defaultClient);
        System.out.println("Default timeout: " + defaultTimeout);
        if (!defaultTimeout.equals(Duration.ofSeconds(30))) {
            throw new AssertionError("Expected default 30s, got " + defaultTimeout);
        }

        // Explicit constructor override
        AuthClient customClient = new AuthClient(Duration.ofSeconds(90));
        Duration customTimeout = getTimeout(customClient);
        System.out.println("Custom timeout: " + customTimeout);
        if (!customTimeout.equals(Duration.ofSeconds(90))) {
            throw new AssertionError("Expected custom 90s, got " + customTimeout);
        }

        // Confirm the timeout is actually applied to the built HttpRequest
        HttpRequest req = HttpRequest.newBuilder(URI.create("http://example.com/oauth/token"))
                .timeout(customTimeout)
                .POST(HttpRequest.BodyPublishers.ofString("x"))
                .build();
        System.out.println("Request timeout: " + req.timeout());
        if (!req.timeout().get().equals(Duration.ofSeconds(90))) {
            throw new AssertionError("Request timeout mismatch");
        }

        System.out.println("ALL CHECKS PASSED");
    }

    private static Duration getTimeout(AuthClient client) throws Exception {
        Field f = AuthClient.class.getDeclaredField("timeout");
        f.setAccessible(true);
        return (Duration) f.get(client);
    }
}
